PRAGMA foreign_keys = ON;
BEGIN;

-- «أذكار الصباح والمساء» as pp29-68 of the 10th edition print them (issue #171):
-- * the opening passages (verses, Al-Shawkani, the two times) are passages to
--   read, the verse lines kept as QuranText because the book quotes them whole;
-- * morning (pp33-43) and evening (pp44-49) follow the book's lists and their
--   numbers; the evening list is not a copy of the morning one, so its
--   «أمسينا على فطرة الإسلام»، «رضيت بالله ربا» and «بسم الله الذي لا يضر»
--   (the last is the first of «ما يقال في الليل») are gone from it;
--   «الصلاة الإبراهيمية» is not in these pages and is gone;
-- * the two «سُوَر» lines read as the book prints them, without the surahs;
-- * «ما يقال في الليل (وأوله بعد المغرب)» (pp50-53) is the third part; it was
--   «ما يقرأ في الليل» with six rows and now has the book's nine;
-- * «من آداب الصباح والمساء» (pp54-68) is the book's eleven adab, each its
--   own passage, with the footnotes under «حاشية:»;
-- * «تنبيه بعد الأذكار الموظفة» (105) is the book's «تنبيه» inside the morning
--   list, and «جواب بعض السلف من سأله: كيف أصبحت؟» (107) is not in the
--   10th edition, so both sections are removed;
-- * a grade is kept only where the book prints «[صحيح]» or «[حسن]» under the
--   dhikr; «[مسلم]»، «[البخاري]»، «[متفق عليه]» is a source and leaves it empty.

DELETE FROM contents WHERE titleId IN (1, 2, 3, 105, 106, 107);
DELETE FROM titles WHERE id IN (105, 107);
UPDATE titles SET "order" = 3 WHERE id = 106;
UPDATE titles SET name = 'ما يُقال في الليل (وأوله بعد المغرب)' WHERE id = 3;
