INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1231, 1, 4, 'إن ذكر الله عز وجل في الصباح والمساء من أشرف الوظائف اليومية الراتبة، وهو أوسع أبواب الأذكار المقيدة رواية، وأعظمها أجرًا.

قال الإمام الشوكاني رحمه الله: «ومن أكثر الأذكار أجورًا، وأعظمها جزاءً: الأدعية الثابتة في الصباح والمساء؛ فإن فيها من النفع والدفع ما هي مشتملة عليه.

فعلى من أحب السلامة من الآفات في الدنيا، والفوز بالخير الآجل والعاجل أن يلازمها ويفعلها في كل صباح ومساء، فإن عسر عليه الإتيان بجميعها أتى ببعض منها».

وقد عيّن الصادق المصدوق ﷺ لهذين الوقتين المباركين أذكارًا كثيرة عظيمة الفضائل والبركات، وهي حصن حصين لمن لزمها، ولأهله وولده وماله، وحرز منيع من كيد شياطين الجن وشياطين الناس، ووسيلة لتحصيل عافية الدنيا والآخرة.', 0, 'أذكار الصباح والمساء. (ص٢٩–٣٠)

حاشية: «قطر الولي على حديث الولي» (ص٤٠٤).

حاشية: فمن وفق للعمل بها كلها فهي نعمة وفضل من الله عز وجل، ومن عجز عن جميعها فليقتصر على قدر يداوم عليه ولو كان ذكرًا واحدًا، وفضل الأكثر الأكثر، والأوسط أقصد، وهو أجدر بأن يدوم عليه، وراجع: «التنبيه» (ص٩).', '', '', 'إن ذكر الله عز وجل في الصباح والمساء من أشرف الوظائف اليومية الراتبة وهو أوسع أبواب الأذكار المقيدة رواية وأعظمها أجرا قال الإمام الشوكاني رحمه الله ومن أكثر الأذكار أجورا وأعظمها جزاء الأدعية الثابتة في الصباح والمساء فإن فيها من النفع والدفع ما هي مشتملة عليه فعلى من أحب السلامة من الآفات في الدنيا والفوز بالخير الآجل والعاجل أن يلازمها ويفعلها في كل صباح ومساء فإن عسر عليه الإتيان بجميعها أتى ببعض منها وقد عين الصادق المصدوق لهذين الوقتين المباركين أذكارا كثيرة عظيمة الفضائل والبركات وهي حصن حصين لمن لزمها ولأهله وولده وماله وحرز منيع من كيد شياطين الجن وشياطين الناس ووسيلة لتحصيل عافية الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1232, 1, 5, 'واعلم -وفقك الله- أن العلماء اختلفوا في تحديد وقت أذكار الصباح والمساء على أقوال؛ أرجحها -والله تعالى أعلم- أن وقت أذكار الصباح يبدأ بطلوع الفجر الصادق إلى طلوع الشمس، وهذا وقتها الفاضل.

ثم يمتد وقتها -تبعًا- إلى ارتفاع الشمس بمقدار رمح (ويقدر بحوالي ١٦ دقيقة)، وهذا وقتها المفضول، وهو أول وقت صلاة الضحى.

ومن فاته هذان الوقتان فليأت بها إلى ما قبل أذان الظهر بوقت يسير.', 0, 'اختلاف العلماء في تحديد وقت أذكار الصباح والمساء. (ص٣١)

حاشية: وليس من الفراغ من صلاة الصبح؛ لأن أذكار الصباح تتعلق بوقته لا بأداء الصلاة، إلا الذكر الذي قيده النص بأنه بعد الصلاة، والكلام نفسه يقال في أذكار المساء التي يبدأ وقتها بدخول وقت العصر.
لكن لما كان الغالب أن المسلم (بعد أذان الفجر يتهيأ للصلاة بالطهور، ثم صلاة ركعتي السنة، ثم المشي إلى المسجد، وما يتعلق به من أذكار، ثم صلاة الصبح، وما يتبعها من أذكار، ثم يتفرغ لأذكار الصباح التي فيها عد وإحصاء وجمع همة) ذكر بعض العلماء أن وقتها يبدأ من بعد صلاة الفجر.', '', '', 'واعلم وفقك الله أن العلماء اختلفوا في تحديد وقت أذكار الصباح والمساء على أقوال أرجحها والله تعالى أعلم أن وقت أذكار الصباح يبدأ بطلوع الفجر الصادق إلى طلوع الشمس وهذا وقتها الفاضل ثم يمتد وقتها تبعا إلى ارتفاع الشمس بمقدار رمح ويقدر بحوالي ١٦ دقيقة وهذا وقتها المفضول وهو أول وقت صلاة الضحى ومن فاته هذان الوقتان فليأت بها إلى ما قبل أذان الظهر بوقت يسير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1, 1, 6, 'أصبحنا على فِطْرَةِ الإسلامِ، وكَلِمَةِ الإخلاصِ، ودِينِ نَبِيِّنَا مُحمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ومِلَّةِ أَبِينَا إبراهيمَ، حنيفًا مُسلِمًا، وما كَانَ مِنَ المُشْرِكِينَ', 1, 'عن عبد الرحمن بن أبزي رضي الله عنه قال: «كان رسول الله صلى الله عليه وسلم يُعلِّمنا إذا أصبح أحدُنا أن يقول -فذكره-». [صحيح على شرط الشيخين]', 'صحيح', '', 'أصبحنا على فطرة الإسلام وكلمة الإخلاص ودين نبينا محمد صلى الله عليه وسلم وملة أبينا إبراهيم حنيفا مسلما وما كان من المشركين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2, 1, 7, 'رَضِيتُ باللهِ رَبًّا، وبالإسلامِ دِينًـا، وبمُحمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّـا', 3, 'عن المُنَيْذِرِ رضي الله عنه قال: سمعتُ رسولَ الله صلى الله عليه وسلم يقول: «من قال إذا أصبح -فذكره- فأنا الزعيم، لآخُذَنَّ بِيَدِهِ حتى أُدخِلَه الجنة». [صحيح]

حاشية: الزعيم: الضامن والكفيل.', 'صحيح', '', 'رضيت بالله ربا وبالإسلام دينا وبمحمد صلى الله عليه وسلم نبيا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (3, 1, 8, 'اللهم بكَ أصبحنا، وبكَ أمسينا، وبكَ نحيا، وبك نموتُ، وإليكَ النشورُ', 1, 'عن أبي هريرة رضي الله عنه قال: «كان النبي صلى الله عليه وسلم إذا أصبح قال: -فذكره-، وإذا أمسى قال: (اللهم بك أمسينا، وبك أصبحنا، وبك نحيا، وبك نموت، وإليك المصير)». [صحيح]', 'صحيح', '', 'اللهم بك أصبحنا وبك أمسينا وبك نحيا وبك نموت وإليك النشور', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (4, 1, 9, 'لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قدير', 1, 'عن أبي عياش رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قال إذا أصبح -فذكره- كان عَدلَ عِتْقِ رقبةٍ من ولد إسماعيل عليه السلام، وكُتِبَ له عَشرُ حسناتٍ، وحُطَّ عنه عَشرُ سيئاتٍ، ورُفِعَ له عَشرُ درجاتٍ، وكان في حِرزٍ من الشيطان حتى يُمسي، فإن قالها إذا أمسى كان له مثلُ ذلك حتى يُصبح». [صحيح]', 'صحيح', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (11, 1, 10, 'اللهم إنِّي أسألُكَ علمًا نافعًا، ورِزْقًا طَيِّبًا، وعَمَلًا مُتَقَبَّلًا', 1, 'عن أم سلمة رضي الله عنها: «أن رسول الله صلى الله عليه وسلم كان إذا أصبح قال...» فذكرَته. [حسن]', 'حسن', '', 'اللهم إني أسألك علما نافعا ورزقا طيبا وعملا متقبلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (5, 1, 11, 'يا حَيُّ يا قَيُّومُ برحمتِك أستغيثُ، أصْلِحْ لي شأني كُلَّه، ولا تَكِلْني إلى نفسي طَرْفَةَ عينٍ أَبَدًا', 1, 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم لفاطمة رضي الله عنها: «ما يمنعك أن تسمعي ما أُوصِيك به؟ أن تقولي إذا أصبحتِ وإذا أمسيتِ» -فذكره-. [حسن]', 'حسن', '', 'يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين أبدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (6, 1, 12, 'آية الكرسي: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ
QuranText[(2:255:255)]', 1, '[البقرة: ٢٥٥]

عن أُبَيِّ بن كعب رضي الله عنه أنه قال للجني: «فما يُنجينا منكم؟» قال: «هذه الآية التي في سورة البقرة: ﴿ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ ﴾ [البقرة: ٢٥٥]، من قالها حين يُمسي أُجِيرَ منا حتى يُصبح، ومَن قالها حين يُصبح أُجِيرَ منا حتى يُمسي»، فلما أصبح أتى رسولَ الله صلى الله عليه وسلم فذكر ذلك له، فقال: «صدق الخبيثُ». [صحيح]', 'صحيح', '', 'آية الكرسي أعوذ بالله من الشيطان الرجيم 2255255', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (9, 1, 13, 'أصْبَحْنَا، وأصبحَ الملكُ للهِ، والحمدُ للهِ، لا إله إلا اللهُ وحده، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ، رَبِّ أسألُكَ خيرَ ما في هذا اليومِ، وخيرَ ما بعدَه، وأعوذُ بكَ مِن شَرِّ ما في هذا اليومِ، وشَرِّ ما بعدَه، رَبِّ أعوذُ بِكَ من الكَسَلِ وسُوءِ الكِبَرِ، رَبِّ أعوذُ بكَ من عذابٍ في النَّارِ وعذابٍ في القَبْرِ', 1, 'عن عبد الله بن مسعود رضي الله عنه قال: «كان نبيُّ الله صلى الله عليه وسلم إذا أمسى قال: «أمسينا» -فذكره-، وإذا أصبح قال ذلك أيضًا: «أصبحنا...» -فذكره-». [مسلم]', '', '', 'أصبحنا وأصبح الملك لله والحمد لله لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير رب أسألك خير ما في هذا اليوم وخير ما بعده وأعوذ بك من شر ما في هذا اليوم وشر ما بعده رب أعوذ بك من الكسل وسوء الكبر رب أعوذ بك من عذاب في النار وعذاب في القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (7, 1, 14, 'اللهم أنت ربي، لا إله إلَّا أنتَ، خلقَتَني، وأنا عبدُك، وأنا على عَهْدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بكَ مِنْ شَرِّ ما صنعتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وأبوءُ بذَنْبي، فَاغْفِرْ لي؛ فإنَّه لا يَغْفِرُ الذُّنُوبَ إلَّا أَنْتَ', 1, 'عن شداد بن أوس رضي الله عنه عن النبي صلى الله عليه وسلم قال: «سيدُ الاستغفار أن يقول العبد: -فذكره- من قالها مُوقنًا بها حين يُمسي، فمات من ليلته؛ دخل الجنة، ومن قالها موقنًا بها حين يُصبح، فمات من يومه؛ دخل الجنة». [البخاري]

حاشية: وتقول المرأة: «وأنا أَمَتُكَ» مكان: «وأنا عبدُكَ» في مثل هذا الموضع على الراجح، قال تعالى: ﴿ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ ﴾ الآية [النور: ٣٢]، فالعطف بالواو للمغايرة؛ لأن العبد خلافُ الأمة.', '', '', 'اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (8, 1, 15, 'اللهمَّ فاطِرَ السماواتِ والأرضِ، عالِمَ الغيبِ والشَّهادةِ، أشهد أن لا إله إلَّا أنت، رَبَّ كُلِّ شيءٍ ومَلِيكَه، أعوذُ بِكَ مِنْ شَرِّ نَفْسِي، ومِن شَرِّ الشيطانِ وشِرْكِه، وأن أَقْتَرِفَ على نفسي سُوءًا، أو أَجُرَّهُ إلى مُسْلِمٍ', 1, 'عن عبد الله بن عمرو رضي الله عنهما: أن أبا بكر رضي الله عنه سأل النبي صلى الله عليه وسلم قال: يا رسول الله علِّمْني ما أقول إذا أصبحتُ وإذا أمسيتُ، فقال: «يا أبا بكر! قُل:...» -فذكره-. [صحيح]

حاشية: وقوله: «وشِرْكِهِ» أي: ما يدعو إليه من الشرك بالله، وبفتح الشين والراء: ما يَصِيد به.', 'صحيح', '', 'اللهم فاطر السماوات والأرض عالم الغيب والشهادة أشهد أن لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي ومن شر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (10, 1, 16, 'اللهم إنِّي أسألُكَ العافيةَ في الدنيا والآخِرةِ، اللهم إنِّي أسألُكَ العفوَ والعافيةَ في ديني ودُنْيايَ، وأهلي، ومالي، اللهم اسْتُرْ عوراتي، وآمِن رَّوْعاتي، اللهم احفظني من بين يَدَيَّ، ومِن خَلْفي، وعن يَميني، وعن شِمالي، ومِن فوقي، وأعوذُ بعظَمَتِكَ أنْ أُغْتَالَ مِنْ تحتي', 1, 'عن ابن عمر رضي الله عنهما قال: «لم يكن رسول الله صلى الله عليه وسلم يَدَعُ هؤلاء الدعوات حين يُصبح، وحين يُمسي» -فذكره-. [صحيح]

حاشية: روعاتي: جمع روعة، وهي الفزعة.

حاشية: والاغتيال: الاحتيال، وحقيقته أن يُدْهَى الإنسان على غفلة منه من حيث لا يشعر، أي: أُخَذَ غِيلةً من تحتي، قال وكيع: «يعني الخسف».', 'صحيح', '', 'اللهم إني أسألك العافية في الدنيا والآخرة اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي اللهم استر عوراتي وآمن روعاتي اللهم احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (12, 1, 17, 'أصبحتُ أُثْني عليكَ حَمْدًا، وأشهدُ أن لا إله إلا الله', 3, 'عن أبي هريرة رضي الله عنه قال رسول الله صلى الله عليه وسلم: «إذا أصبح أحدُكم فليقل: -فذكره-، وإذا أمسى فليقل مثل ذلك». [حسن]', 'حسن', '', 'أصبحت أثني عليك حمدا وأشهد أن لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (13, 1, 18, 'باسمِ اللهِ الذي لا يَضُرُّ مع اسمِه شيءٌ في الأرضِ ولا في السماءِ، وهو السَّمِيعُ العليمُ', 3, 'عن عثمان رضي الله عنه قال: سمعتُ رسول الله صلى الله عليه وسلم يقول: «ما من عبدٍ يقول في صباح كل يوم، ومساء كل ليلة: -فذكره- فيضرَّه شيء». [صحيح]', 'صحيح', '', 'باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (14, 1, 19, 'سُبْحانَ اللهِ عدَدَ خَلْقِه، سُبْحانَ اللهِ رِضَا نفسِه، سُبْحانَ اللهِ زِنَةَ عَرْشِه، سُبْحانَ اللهِ مِدادَ كَلِماتِه
أو: سبحانَ اللهِ وبحمدِهِ عددَ خَلْقِه، ورِضا نفسِه، وزِنَةَ عَرْشِه، ومِدادَ كَلِماتِه', 3, 'عن جويرية رضي الله عنها أن النبي صلى الله عليه وسلم خرج من عندها بُكرة حين صلى الصبح، وهي في مسجدها، ثم رجع بعد أن أضحى، وهي جالسة، فقال: «ما زِلتِ على الحال التي فارقتُكِ عليها؟»، قالت: نعم، قال النبي صلى الله عليه وسلم: «لقد قلتُ بعدَكِ أربعَ كلمات، ثلاثَ مرّات، لو وُزِنت بما قلتِ منذ اليوم لَوَزَنَتْهُنَّ -فذكره-». [مسلم]', '', '', 'سبحان الله عدد خلقه سبحان الله رضا نفسه سبحان الله زنة عرشه سبحان الله مداد كلماته أو سبحان الله وبحمده عدد خلقه ورضا نفسه وزنة عرشه ومداد كلماته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (15, 1, 20, 'اللهم عافِني في بدني، اللهم عافِني في سَمْعِي، اللهم عافِني في بصري، لا إله إلَّا أنْتَ', 3, '', '', '', 'اللهم عافني في بدني اللهم عافني في سمعي اللهم عافني في بصري لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (16, 1, 21, 'اللهم إنِّي أعوذُ بِكَ مِنَ الكُفْرِ والفقرِ، اللهم إنِّي أعوذُ بِكَ من عذابِ القبرِ، لا إله إلَّا أنْتَ', 3, 'عن عبد الرحمن بن أبي بكرة أنه قال لأبيه: يا أبتِ، إني أسمعك تدعو كل غداة -فذكره-، ثم قال: تُعيدها ثلاثًا حين تصبح، وثلاثًا حين تُمسي، فقال: «نعم، يا بُنيَّ، سمعتُ رسول الله صلى الله عليه وسلم يقول بهن، وأنا أُحبُّ أن أستَنَّ بِسُنَّتِه». [حسن]', 'حسن', '', 'اللهم إني أعوذ بك من الكفر والفقر اللهم إني أعوذ بك من عذاب القبر لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (17, 1, 22, 'سُوَر: (الإخلاص)، و(الفلق)، و(الناس)', 3, 'عن عبد الله بن خُبيب رضي الله عنه أن النبي صلى الله عليه وسلم أمره أن يقرأ: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، والمعوذتين «حين تُمسي، وحين تُصبح، ثلاثَ مرّات، تكفيك من كل شيء». [حسن]', 'حسن', '', 'سور الإخلاص و الفلق و الناس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (18, 1, 23, '﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', 7, '[التوبة: ١٢٩]

عن أبي الدرداء رضي الله عنه قال: «من قال إذا أصبح، وإذا أمسى: ﴿ حَسۡبِيَ ٱللَّهُ... ﴾ الآية [التوبة: ١٢٩] سبعَ مرّات؛ كفاه الله ما أهمَّه». [موقوف صحيح، له حكم الرفع]', 'صحيح', '', 'حسبي الله لآ إله إلا هو عليه توكلت وهو رب العرش العظيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (19, 1, 24, 'لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، يُحْيِي ويُمِيتُ، وهُوَ على كُلِّ شيءٍ قديرٌ', 10, 'عن أبي أيوب الأنصاري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من قال حين يصبح -فذكره- كُتِبَ الله له بكل واحدة قالها عشر حسنات، وحَطَّ الله عنه بها عشر سيئات، ورَفَعَه الله بها عشر درجات، وكُنَّ له كعشر رقاب، وكُنَّ له مَسْلَحةً من أول النهار إلى آخره، ولم يعمل يومئذ عملًا يقهرهنَّ، فإن قال حين يُمسي، فمثل ذلك». [صحيح]', 'صحيح', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (23, 1, 25, 'أستغفِرُ اللهَ', 100, 'عن أبي موسى الأشعري رضي الله عنه قال: جاء رسول الله صلى الله عليه وسلم ونحن جلوس، فقال: «ما أصبحتُ غداةً قطُّ إلا استغفرتُ الله فيها مئةَ مرّة». [صحيح]

حاشية: ولم يوظَّف هنا صيغة معيَّنة للاستغفار، وأخصرها المذكور، وأفضلها المأثور، ولا سيَّما (سيد الاستغفار).

حاشية: وقد اقتبس الشوكاني رحمه الله من قوله تعالى: ﴿ وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ ﴾ [هود: ٣] صيغة: «اللهم إني أستغفرك فاغفر لي، وأتوب إليك فتب عليَّ» كما في «تحفة الذاكرين» (ص٤٠١).', 'صحيح', '', 'أستغفر الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (21, 1, 26, 'سبحانَ اللهِ وبحمدِهِ
أو: سبحانَ اللهِ العظيمِ وبحمدِهِ', 100, 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قال حين يُصبح، وحين يُمسي: (سبحان الله وبحمده) مئة مرّة؛ لم يأتِ أحدٌ يوم القيامة بأفضل مما جاء به، إلا أحدٌ قال مثل ما قال، أو زاد عليه». [مسلم] وفي رواية أبي داود: «من قال حين يُصبح: (سبحان الله العظيم وبحمده) مئة مرّة، وإذا أمسى كذلك؛ لم يُوافِ أحدٌ من الخلائق بمثل ما وافى». [صحيح]

حاشية: وافى: أتى، واستوفيت حقي: أخذتُه تامًّا.', 'صحيح', '', 'سبحان الله وبحمده أو سبحان الله العظيم وبحمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (24, 1, 27, 'سبحانَ اللهِ', 100, '', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (25, 1, 28, 'الحمدُ للهِ', 100, '', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (26, 1, 29, 'اللهُ أكبرُ', 100, '', '', '', 'الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (27, 1, 30, 'لا إله إلا الله وحده، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ', 100, 'عن عمرو بن شعيب، عن أبيه، عن جده: قال رسول الله صلى الله عليه وسلم: «من قال: (سبحان الله) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من مئة بَدَنة، ومن قال: (الحمد لله) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من مئة فرسٍ يُحمل عليها في سبيل الله، ومن قال: (الله أكبر) مئة مرة قبل طلوع الشمس، وقبل غروبها، كان أفضل من عِتق مئة رقبة، ومن قال: (لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير) مئة مرة قبل طلوع الشمس، وقبل غروبها، لم يَجِئْ يوم القيامة أحدٌ بعمل أفضل من عمله إلا مَن قال مثل قوله، أو زاد عليه». [حسن]', 'حسن', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1233, 1, 31, 'أو يقول: لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ', 100, 'عن عمرو بن شعيب، عن أبيه، عن جده صلى الله عليه وسلم قال: «من قال في يوم مئتَي مرّة [مئةً إذا أصبح، ومئةً إذا أمسى]: (لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير)؛ لم يسبقه أحدٌ كان قبله، ولا يُدركه أحدٌ كان بعده، إلا مَن عمل أفضل من عمله». [حسن]', 'حسن', '', 'أو يقول لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1194, 1, 32, 'تنبيه:
فإذا فرغ من الأذكار الموظفة؛ استُحِبَّ له أن يشرع في الأذكار والأدعية المطلقة، وأفضلها على الإطلاق: قراءة القرآن الكريم، ثم التهليل، والصلاة على النبي صلى الله عليه وسلم، ثم الاستغفار، والتسبيح، والتحميد، والتكبير، والحولقة، وغيرها.', 0, 'تنبيه. (ص٤٢–٤٣)

حاشية: ويأتي ذكر صيغ كل واحد من الأذكار المطلقة عقب كل نوع منها إن شاء الله (ص٢٤٧) وما بعدها.', '', '', 'تنبيه فإذا فرغ من الأذكار الموظفة استحب له أن يشرع في الأذكار والأدعية المطلقة وأفضلها على الإطلاق قراءة القرآن الكريم ثم التهليل والصلاة على النبي صلى الله عليه وسلم ثم الاستغفار والتسبيح والتحميد والتكبير والحولقة وغيرها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1234, 1, 33, 'فإذا قام عن مجلسه ختمه بكفارة المجلس:', 0, 'كفارة المجلس. (ص٤٣)', '', '', 'فإذا قام عن مجلسه ختمه بكفارة المجلس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (28, 1, 34, 'سبحان الله وبحمده،
سُبحانَكَ اللهمَّ وبحمدِكَ،
أشهدُ أن لا إله إلا أنت،
أستغفِرُكَ، وأتوبُ إليكَ', 1, 'عن جُبَير بن مُطْعِم رضي الله عنه مرفوعًا: «من قال: ...، فقالها في مجلس ذكر؛ كانت كالطابَع يُطبع عليه، ومن قالها في مجلس لغو؛ كانت كفارةً له». [صحيح على شرط مسلم]

وعن أم المؤمنين عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم كان إذا جلس مَجْلِسًا، أو صلّى صلاةً؛ تكلَّم بكلمات، فسألَتْه عائشةُ عن الكلمات، فقال: «إن تكلَّم بخير كان طابَعًا عليهنَّ إلى يوم القيامة، وإن تكلَّم بغير ذلك كان كفارةً له: (سبحانك اللهم وبحمدك، لا إله إلا أنت، أستغفرك وأتوب إليك)». [صحيح]

حاشية: وقوله: «كالطابع»: هو الخاتَم على الصحيفة، يريد أنه يُختَم عليها، وتُرفَع، كما يفعل الإنسانُ بما يَعِزُّ عليه. انظر: «النهاية» (٣/ ١١٢).
وقيل: طابَع عليه، أي: خاتَم عليه، إما على الحقيقة أو التشبيه، والمقصود: أن عمله محفوظ لا يضيع أبدًا.
وقال السندي: «المراد أنه يكون مُثبَّتًا لذلك الخير، رافعًا له إلى درجة القبول، آمنًا له عن حضيض الرَّد، وإن كان غير ذلك كان كفارة له»، انظر: «مرعاة المفاتيح» (٨/ ٢٠٤).', 'صحيح', '', 'سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1235, 2, 1, 'أما أذكار المساء فيبدأ وقتها من دخول وقت صلاة العصر إلى غروب الشمس، ويمتد -تبعًا- إلى أن يمضي ثلث الليل، وقيل: نصفه.', 0, 'اختلاف العلماء في تحديد وقت أذكار الصباح والمساء. (ص٣٢)

حاشية: وهذا في الأذكار التي نُصَّ على أنها تُقال في المساء، أما الأذكار التي قيَّدها النص بأنها تُقال في الليل، فتُقال بعد غروب الشمس، ويمتدُّ وقتها إلى هزيع من الليل، وذلك لأنَّ لفظ (المساء) يدخل فيه ما بعد العصر إلى غروب الشمس، وقد يُطلَق على (الليل)، أمَّا (الليل) فلا يُطلَق إلا على (ما يلي غروب الشمس).', '', '', 'أما أذكار المساء فيبدأ وقتها من دخول وقت صلاة العصر إلى غروب الشمس ويمتد تبعا إلى أن يمضي ثلث الليل وقيل نصفه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (32, 2, 2, 'اللهم بِكَ أمسينا، وبِكَ أصبحنا، وبِكَ نحيا، وبِكَ نموتُ، وإليكَ المصِيرُ', 1, '', '', '', 'اللهم بك أمسينا وبك أصبحنا وبك نحيا وبك نموت وإليك المصير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (33, 2, 3, 'لا إلهَ إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قدير', 1, '', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (34, 2, 4, 'يا حَيُّ يا قَيُّومُ، بِرَحْمَتِكَ أستغيثُ، أَصْلِحْ لي شأني كُلَّه، ولا تَكِلْنِي إلى نفسي طَرْفَةَ عينٍ أَبَدًا', 1, '', '', '', 'يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين أبدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (35, 2, 5, 'آية الكرسي: أَعُوذُ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ
QuranText[(2:255:255)]', 1, '[البقرة: ٢٥٥]', '', '', 'آية الكرسي أعوذ بالله من الشيطن الرجيم 2255255', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (38, 2, 6, 'أمسينا، وأمسى المُلْكُ لله، والحمدُ لله، لا إله إلا اللهُ وحدَهُ، لا شريكَ له، له المُلْكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ، رَبِّ أسألُكَ خيرَ ما في هذه الليلةِ، وخيرَ ما بعدَها، وأعوذُ بِكَ مِنْ شَرِّ ما في هذه الليلةِ، وشَرِّ ما بعدَها، رَبِّ أعوذُ بِكَ من الكَسَلِ وسوءِ الكِبَرِ، رَبِّ أعوذُ بِكَ من عذابٍ في النَّارِ، وعذابٍ في القَبْرِ', 1, '', '', '', 'أمسينا وأمسى الملك لله والحمد لله لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير رب أسألك خير ما في هذه الليلة وخير ما بعدها وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها رب أعوذ بك من الكسل وسوء الكبر رب أعوذ بك من عذاب في النار وعذاب في القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (36, 2, 7, 'اللهم أنتَ رَبِّي، لا إلهَ إلا أنتَ، خَلَقْتَنِي، وأنا عبدُك، وأنا على عَهْدِكَ وَوَعْدِكَ ما استطعتُ، أعوذُ بِكَ مِنْ شَرِّ ما صنعتُ، أبوءُ لكَ بنعمتِكَ عَلَيَّ، وأبوءُ بذنبي، فاغفِرْ لِي؛ فإنَّه لا يَغْفِرُ الذنوبَ إلَّا أَنْتَ', 1, 'حاشية: سيِّدُ الاستغفار، يُقال في المساء، أو يُقال ليلًا؛ لأنَّ في بعض رواياته: «ومن قالها من الليل» الحديث.', '', '', 'اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (37, 2, 8, 'اللهم فاطِرَ السماواتِ والأرضِ، عالِمَ الغيبِ والشَّهادةِ، أشهد أن لا إله إلَّا أنْتَ، رَبَّ كُلِّ شيءٍ ومَلِيكَه، أعوذُ بِكَ من شَرِّ نفسي، وشَرِّ الشيطانِ وشِرْكِه، وأن أقتَرِفَ على نفسي سُوءًا، أو أجرَّه إلى مُسْلِمٍ', 1, '', '', '', 'اللهم فاطر السماوات والأرض عالم الغيب والشهادة أشهد أن لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي وشر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (39, 2, 9, 'اللهم إنِّي أسألُكَ العافيةَ في الدنيا والآخرة، اللهم إنِّي أسألُكَ العفوَ والعافيةَ في ديني، ودُنْيايَ، وأهلي، ومالي، اللهم اسْتُرْ عَوْراتي، وآمِن رَّوْعاتي، اللهم احفظني مِن بينِ يدَيَّ، ومِن خَلْفي، وعن يَميني، وعن شِمالي، ومِن فوقي، وأعوذُ بعَظَمَتِكَ أَنْ أُغْتالَ مِنْ تحتي', 1, '', '', '', 'اللهم إني أسألك العافية في الدنيا والآخرة اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي اللهم استر عوراتي وآمن روعاتي اللهم احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (41, 2, 10, 'أمسيتُ أُثْني عليكَ حمدًا، وأشهدُ أن لا إله إلا الله', 3, '', '', '', 'أمسيت أثني عليك حمدا وأشهد أن لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (40, 2, 11, 'أعوذُ بكلماتِ اللهِ التَّامَّاتِ مِن شَرِّ ما خَلَقَ', 3, 'عن أبي هريرة، قال: جاء رجلٌ إلى النبي صلى الله عليه وسلم فقال: يا رسول الله، ما لقيتُ من عقربٍ لَدَغَتْنِي البارحةَ؟ قال: «أمَا لو قلتَ حين أمسيتَ -فذكره- لم تَضُرَّكَ». [مسلم] وفي رواية للترمذي وغيره: «ثلاثَ مرّاتٍ». [صحيح]', 'صحيح', '', 'أعوذ بكلمات الله التامات من شر ما خلق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (43, 2, 12, 'اللهم عافِني في بدني، اللهم عافِني في سَمْعي، اللهم عافِني في بصري، لا إله إلَّا أنْتَ', 3, '', '', '', 'اللهم عافني في بدني اللهم عافني في سمعي اللهم عافني في بصري لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (44, 2, 13, 'اللهم إنِّي أعوذُ بِكَ من الكُفْرِ والفَقْرِ، اللهم إنِّي أعوذُ بِكَ من عذابِ القبرِ، لا إله إلَّا أنتَ', 3, '', '', '', 'اللهم إني أعوذ بك من الكفر والفقر اللهم إني أعوذ بك من عذاب القبر لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (45, 2, 14, 'سُوَر: (الإخلاص)، و(الفلق)، و(الناس)', 3, '', '', '', 'سور الإخلاص و الفلق و الناس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (46, 2, 15, '﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', 7, '[التوبة: ١٢٩]', '', '', 'حسبي الله لآ إله إلا هو عليه توكلت وهو رب العرش العظيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (47, 2, 16, 'لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، يُحْيِي ويُمِيتُ، وهُوَ على كُلِّ شيءٍ قديرٌ', 10, '', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (49, 2, 17, 'سُبحانَ اللهِ وبحمدِهِ
أو: سُبحانَ اللهِ العظيمِ وبحمدِهِ', 100, '', '', '', 'سبحان الله وبحمده أو سبحان الله العظيم وبحمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (52, 2, 18, 'سُبحانَ اللهِ', 100, '', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (883, 2, 19, 'الحمدُ للهِ', 100, '', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (884, 2, 20, 'اللهُ أكبرُ', 100, '', '', '', 'الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (885, 2, 21, 'لا إله إلا الله وحده لا شريكَ له، له المُلْكُ، وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ', 100, '', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1236, 2, 22, 'أو يقول: لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ', 100, 'حاشية: انظر: الحاشية رقم (١) (ص٤٢).', '', '', 'أو يقول لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (886, 2, 23, 'سبحان الله وبحمده،
سُبحانَكَ اللهمَّ وبحمدِكَ،
أشهدُ أن لا إله إلا أنت،
أستغفِرُكَ، وأتوبُ إليكَ', 1, '', '', '', 'سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (53, 3, 1, 'باسمِ اللهِ الذي لا يَضُرُّ مع اسمِه شيءٌ في الأرضِ ولا في السماءِ، وهو السَّمِيعُ العليمُ', 3, 'حاشية: ومع أن وقتها ممتدٌّ حتى آخر ثلث الليل الأول، إلا أن الأفضل أن يأتيَ بها في أوَّل وقتها -أي: بعد الغروب- ما أمكن؛ مبادرةً بالأعمال، وحذرًا من التسويف؛ لأن العمل المؤجَّل -في الغالب- ضائع.', '', '', 'باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (54, 3, 2, 'QuranText[(112:1:4)]', 1, '[الإخلاص]

حاشية: تواترت الأحاديث بكون ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ تعدل ثلث القرآن:
منها: ما رواه أبو سعيد الخدري رضي الله عنه أنه عن النبي صلى الله عليه وسلم قال: «أيَعجِزُ أحدُكم أن يقرأ ثُلُثَ القرآنِ في ليلة؟» قال: فشقَّ ذلك على أصحابه، فقالوا: من يُطيقُ ذلك؟ قال: «يقرأ: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ فهي ثُلُثُ القرآن». [البخاري]
والمقصود أن قراءتها لها جزاءُ وثوابُ قراءة ثُلُث القرآن، لكنها لا تُجزئ عن قراءة ثلث القرآن الكريم.', '', '', '11214', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (55, 3, 3, 'آخر سورة البقرة:
QuranText[(2:285:286)]', 1, '[البقرة: ٢٨٥، ٢٨٦]

عن أبي مسعود البدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه». [متفق عليه]

حاشية: «كفتاه»: أي أجزأتاه عن قيام الليل، وقيل: كفتاه من كل شيطان، فلا يقربه ليلته؛ وقيل: كفتاه ما يكون من الآفات التي تكون في تلك الليلة، وقيل: معناه حسبه بها فضلًا وأجرًا، ولا مانع من إرادة هذه الأمور جميعها، ويؤيده: أن حذف المتعلق مشعر بالتعميم، فكأنه قال: «كفتاه من كل شر، أو من كل ما يخاف، وفضل الله واسع» أفاده الشوكاني. انظر: «تحفة الذاكرين» (ص٩٩، ٢٣٥).
وروى مسلم أن مَلَكًا قال للنبي صلى الله عليه وسلم: «أبشر بنورين أوتيتَهما، لم يؤتهما نبيٌّ قبلك: فاتحةِ الكتاب، وخواتيمِ سورة البقرة، لن تقرأ بحرفٍ منهما إلا أُعطيتَه».', '', '', 'آخر سورة البقرة 2285286', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (56, 3, 4, 'سورة: ﴿ تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ ﴾', 1, 'عن عبد الله بن مسعود رضي الله عنه قال: «من قرأ: ﴿ تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ ﴾ كلَّ ليلة؛ منعه الله بها من عذاب القبر، وكنا في عهد رسول الله صلى الله عليه وسلم نُسمِّيها (المانعة)، وإنها في كتاب الله سورة من قرأ بها في كل ليلة فقد أكثر وأطاب». [موقوف حسن]
وعنه رضي الله عنه قال: «يُؤتى الرجل في قبره، فيُؤتى رجلاه، فيقولان: ليس لكم على ما قِبَلَنا من سبيل؛ كان يقرأ علينا سورة الملك، ثم يُؤتى جَوْفُه فيقول: ليس لكم عليَّ سبيل؛ قد وَعَى فيَّ سورة الملك، ثم يُؤتى من رأسه فيقول: ليس لكم على ما قِبَلي سبيل؛ كان يقرأ فيَّ سورة الملك». قال عبد الله: «فهي المانعة تمنع عذاب القبر، وهي في التوراة هذه سورة الملك من قرأها في ليلة أكثر وأطيب». [موقوف حسن]
ومثل هذا لا يُقال من قِبَل الرأي؛ فله حُكمُ المرفوع.', 'حسن', '', 'سورة تبرك الذي بيده الملك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (887, 3, 5, 'وكان النبي صلى الله عليه وسلم لا ينام حتى يقرأ: (بني إسرائيل) و(الزُّمَر).', 1, 'حاشية: وسورة (بني إسرائيل) هي سورة (الإسراء)، وتُسمَّى أيضًا سورة (سُبحان).', '', '', 'وكان النبي صلى الله عليه وسلم لا ينام حتى يقرأ بني إسرائيل و الزمر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (888, 3, 6, 'وكان صلى الله عليه وسلم لا ينام حتى يقرأ (السَّجْدَة) و(المُلْك).', 1, '', '', '', 'وكان صلى الله عليه وسلم لا ينام حتى يقرأ السجدة و الملك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1237, 3, 7, 'وكان يقرأ «المسبِّحات» قبل أن ينام، وإذا اضطجع.', 1, 'حاشية: قال ابن الأثير رحمه الله: «المسبحات هي السور التي في أولها: ﴿ سَبَّحَ لِلَّهِ ﴾، أو ﴿ يُسَبِّحُ لِلَّهِ ﴾، أو ﴿ سَبِّحِ ٱسۡمَ رَبِّكَ ﴾».اهـ. من «جامع الأصول» (٤/ ٢٦٥)، وقيل: «هي: الحديد، والحشر، والصف، والجمعة، والتغابن».

حاشية: تنبيه: إذا قرأ كل ما تقدَّم فهي نعمة من الله وفضل، وإلا فَلْيَقرأْ بعضه في يوم، ثم يأتي بغيره في يوم آخَر كما تقدَّم (ص٩، ١٠).', '', '', 'وكان يقرأ المسبحات قبل أن ينام وإذا اضطجع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1238, 3, 8, 'سيد الاستغفار.', 1, 'حاشية: انظر (ص٣٦، ٤٥)، وانظر: «رواء الظماء» (ص٨٢).', '', '', 'سيد الاستغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1239, 3, 9, 'ومن قرأ عشر آيات من القرآن الكريم في صلاة القيام لم يُكتَب من الغافلين، ومن قرأ مئة آية كُتب من القانتين، ومن قرأ ألفَ آية كُتب من المُقنطِرين.', 1, 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قرأ عشر آيات في ليلة؛ لم يُكتَب من الغافلين». [صحيح لغيره]
وعن تميم الداري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من قرأ بمئة آية في ليلة؛ كُتب له قُنوتُ ليلة». [حسن بشواهده]
وعن عبد الله بن عمرو رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قام بعشر آيات؛ لم يُكتَب من الغافلين، ومن قرأ بمئة آية؛ كُتِب من القانتين؛ ومن قام بألف آية؛ كُتِب من المُقنطِرين». [صحيح]
وقد ترجم له ابن حبان في (أبواب قيام الليل): «ذكر نفي الغفلة عمَّن قام الليل بعشر آياتٍ».', '', '', 'ومن قرأ عشر آيات من القرآن الكريم في صلاة القيام لم يكتب من الغافلين ومن قرأ مئة آية كتب من القانتين ومن قرأ ألف آية كتب من المقنطرين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1013, 106, 1, 'الأول: أن يستحضر أن الله سبحانه وتعالى يستعتبه، ويمدّ في أجله؛ عسى أن يتوب إليه، ويقبل عليه؛ ولهذا المعنى كان ﷺ إذا استيقظ من نومه، قال: «الحمد لله الذي ردّ علي روحي، وعافاني في جسدي، وأذن لي بذكره». [حسن]

وقال رسول الله ﷺ: «ليس أحد أفضل عند الله من مؤمن يُعمَّر في الإسلام؛ لتسبيحه، وتكبيره، وتهليله». [حسن]

– وقال ابن مسعود رضي الله عنه لجاريته حين أخبرته بطلوع الشمس: «الحمد لله الذي وهب لنا هذا اليوم، وأقالنا فيه عثراتنا، ولم يعذبنا بالنار».

– وقال سعيد بن جبير رحمه الله: «كل يوم يعيشه المؤمن غنيمة».

– قال محمود الورّاق:
يحبّ الفتى طول البقاء كأنه
على ثقة أن البقاء بقاء
إذا ما طوى يومًا اليوم بعضه
ويطويه إن جنّ المساء مساء', 0, 'من آداب الصباح والمساء. (ص٥٤–٥٥)', '', '', 'الأول أن يستحضر أن الله سبحانه وتعالى يستعتبه ويمد في أجله عسى أن يتوب إليه ويقبل عليه ولهذا المعنى كان إذا استيقظ من نومه قال الحمد لله الذي رد علي روحي وعافاني في جسدي وأذن لي بذكره حسن وقال رسول الله ليس أحد أفضل عند الله من مؤمن يعمر في الإسلام لتسبيحه وتكبيره وتهليله حسن وقال ابن مسعود رضي الله عنه لجاريته حين أخبرته بطلوع الشمس الحمد لله الذي وهب لنا هذا اليوم وأقالنا فيه عثراتنا ولم يعذبنا بالنار وقال سعيد بن جبير رحمه الله كل يوم يعيشه المؤمن غنيمة قال محمود الوراق يحب الفتى طول البقاء كأنه على ثقة أن البقاء بقاء إذا ما طوى يوما اليوم بعضه ويطويه إن جن المساء مساء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1240, 106, 2, 'الثاني: أن يلتزم الاستغفار، ويجدد التوبة من جميع الذنوب؛ بالكف عنها، والندم عليها، والعزم الأكيد على عدم معاودتها، وأداء الحقوق إلى أصحابها.

عن أبي موسى رضي الله عنه أن رسول الله ﷺ قال: «إن الله تعالى يبسط يده بالليل؛ ليتوب مسيء النهار، ويبسط يده بالنهار؛ ليتوب مسيء الليل حتى تطلع الشمس من مغربها». [مسلم]

قال طلق بن حبيب: «إن حقوق الله تعالى أعظم من أن يقوم بها العباد، وإن نعم الله أكثر من أن تحصى، ولكن أصبحوا تائبين، وأمسوا تائبين».

– وقال رجل لحاتم الأصم: ما تشتهي؟ قال: «أشتهي عافية يوم إلى الليل»، فقال له: أليست الأيام كلها عافية؟ قال: «إن عافية يومي ألّا أعصي الله فيه».', 0, 'من آداب الصباح والمساء. (ص٥٥–٥٦)', '', '', 'الثاني أن يلتزم الاستغفار ويجدد التوبة من جميع الذنوب بالكف عنها والندم عليها والعزم الأكيد على عدم معاودتها وأداء الحقوق إلى أصحابها عن أبي موسى رضي الله عنه أن رسول الله قال إن الله تعالى يبسط يده بالليل ليتوب مسيء النهار ويبسط يده بالنهار ليتوب مسيء الليل حتى تطلع الشمس من مغربها مسلم قال طلق بن حبيب إن حقوق الله تعالى أعظم من أن يقوم بها العباد وإن نعم الله أكثر من أن تحصى ولكن أصبحوا تائبين وأمسوا تائبين وقال رجل لحاتم الأصم ما تشتهي قال أشتهي عافية يوم إلى الليل فقال له أليست الأيام كلها عافية قال إن عافية يومي ألا أعصي الله فيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1241, 106, 3, 'الثالث: أن يصبح ولا هم له أكبر من إرضاء الله تعالى، والاستعداد للآخرة؛ قال ﷺ: «من كانت همّته الآخرة، جمع الله له شمله، وجعل غناه في قلبه، وأتته الدنيا راغمة، ومن كانت همّته الدنيا، فرّق الله عليه أمره، وجعل فقره بين عينيه، ولم يأتِه من الدنيا إلا ما كتب الله له». [صحيح]

وذلك يقتضي أن يجتهد في تعمير وقته، وشغل قلبه بكل ما يرضي الله من صالح الأعمال.', 0, 'من آداب الصباح والمساء. (ص٥٦–٥٧)', '', '', 'الثالث أن يصبح ولا هم له أكبر من إرضاء الله تعالى والاستعداد للآخرة قال من كانت همته الآخرة جمع الله له شمله وجعل غناه في قلبه وأتته الدنيا راغمة ومن كانت همته الدنيا فرق الله عليه أمره وجعل فقره بين عينيه ولم يأته من الدنيا إلا ما كتب الله له صحيح وذلك يقتضي أن يجتهد في تعمير وقته وشغل قلبه بكل ما يرضي الله من صالح الأعمال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1242, 106, 4, 'الرابع: أن يعزم على كف شرّه عن الناس، ويطهّر قلبه من الغل لأيٍّ من المسلمين؛ فعن أنس بن مالك رضي الله عنه، قال: كنا جلوسًا مع رسول الله ﷺ فقال: «يطلع عليكم الآن رجل من أهل الجنة»، فطلع رجل من الأنصار، تنطف لحيته من وضوئه، قد تعلّق نعليه في يده الشمال، فلما كان الغد، قال النبي ﷺ مثل ذلك، فطلع ذلك الرجل مثل المرة الأولى، فلما كان اليوم الثالث، قال النبي ﷺ مثل مقالته أيضًا، فطلع ذلك الرجل على مثل حاله الأولى، فلما قام النبي ﷺ تبعه عبد الله بن عمرو بن العاص رضي الله عنهما فقال: إني لاحيت أبي، فأقسمت ألا أدخل عليه ثلاثًا، فإن رأيت أن تؤويني إليك حتى تمضي فعلت؟ قال: نعم.

قال أنس: وكان عبد الله يحدّث أنه بات معه تلك الليالي الثلاث، فلم يره يقوم من الليل شيئًا، غير أنه إذا تعارّ وتقلّب على فراشه ذكر الله عز وجل، وكبّر، حتى يقوم لصلاة الفجر. قال عبد الله: غير أني لم أسمعه يقول إلا خيرًا، فلما مضت الثلاث ليالٍ، وكدت أن أحقر عمله، قلت: يا عبد الله، إني لم يكن بيني وبين أبي غضب ولا هجر ثَمّ، ولكن سمعت رسول الله ﷺ يقول لك ثلاث مرار: «يطلع عليكم الآن رجل من أهل الجنة»، فطلعت أنت الثلاث مرار، فأردت أن آوي إليك؛ لأنظر ما عملك، فأقتدي به، فلم أرك تعمل كثير عمل، فما الذي بلغ بك ما قال رسول الله ﷺ؟! فقال: ما هو إلا ما رأيت، قال: فلما وليت دعاني، فقال: ما هو إلا ما رأيت غير أني لا أجد في نفسي لأحد من المسلمين غشًّا، ولا أحسد أحدًا على خير أعطاه الله عز وجل إياه، فقال عبد الله: هذه التي بلغت بك، وهي التي لا نطيق. [صحيح على شرط الشيخين]', 0, 'من آداب الصباح والمساء. (ص٥٧–٥٩)', '', '', 'الرابع أن يعزم على كف شره عن الناس ويطهر قلبه من الغل لأي من المسلمين فعن أنس بن مالك رضي الله عنه قال كنا جلوسا مع رسول الله فقال يطلع عليكم الآن رجل من أهل الجنة فطلع رجل من الأنصار تنطف لحيته من وضوئه قد تعلق نعليه في يده الشمال فلما كان الغد قال النبي مثل ذلك فطلع ذلك الرجل مثل المرة الأولى فلما كان اليوم الثالث قال النبي مثل مقالته أيضا فطلع ذلك الرجل على مثل حاله الأولى فلما قام النبي تبعه عبد الله بن عمرو بن العاص رضي الله عنهما فقال إني لاحيت أبي فأقسمت ألا أدخل عليه ثلاثا فإن رأيت أن تؤويني إليك حتى تمضي فعلت قال نعم قال أنس وكان عبد الله يحدث أنه بات معه تلك الليالي الثلاث فلم يره يقوم من الليل شيئا غير أنه إذا تعار وتقلب على فراشه ذكر الله عز وجل وكبر حتى يقوم لصلاة الفجر قال عبد الله غير أني لم أسمعه يقول إلا خيرا فلما مضت الثلاث ليال وكدت أن أحقر عمله قلت يا عبد الله إني لم يكن بيني وبين أبي غضب ولا هجر ثم ولكن سمعت رسول الله يقول لك ثلاث مرار يطلع عليكم الآن رجل من أهل الجنة فطلعت أنت الثلاث مرار فأردت أن آوي إليك لأنظر ما عملك فأقتدي به فلم أرك تعمل كثير عمل فما الذي بلغ بك ما قال رسول الله ! فقال ما هو إلا ما رأيت قال فلما وليت دعاني فقال ما هو إلا ما رأيت غير أني لا أجد في نفسي لأحد من المسلمين غشا ولا أحسد أحدا على خير أعطاه الله عز وجل إياه فقال عبد الله هذه التي بلغت بك وهي التي لا نطيق صحيح على شرط الشيخين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1243, 106, 5, 'الخامس: أن يستحضر قول أبي سعيد الخدري رضي الله عنه: «إذا أصبح ابن آدم فإن الأعضاء كلها تكفّر اللسان، تقول: اتق الله فينا فإنما نحن بك، فإن استقمت استقمنا، وإن اعوججت اعوججنا». [موقوف حسن، له حكم المرفوع]

وقوله ﷺ: «أكثر خطايا ابن آدم في لسانه». [جيد]', 0, 'من آداب الصباح والمساء. (ص٥٩)

حاشية: «تُكَفِّرُ اللسان»: تتذلل وتخضع له، قال في «النهاية»: «التكفير: هو أن ينحني الإنسان، ويطأطئ رأسه قريبًا من الركوع، كما يفعل من يريد تعظيم صاحبه».', '', '', 'الخامس أن يستحضر قول أبي سعيد الخدري رضي الله عنه إذا أصبح ابن آدم فإن الأعضاء كلها تكفر اللسان تقول اتق الله فينا فإنما نحن بك فإن استقمت استقمنا وإن اعوججت اعوججنا موقوف حسن له حكم المرفوع وقوله أكثر خطايا ابن آدم في لسانه جيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1244, 106, 6, 'السادس: أن يمكث في مصلاه بعد صلاة الصبح يذكر الله حتى تطلع الشمس، ثم يصلي ركعتين، وأن يمكث كذلك -يذكر الله- بعد صلاة العصر؛ فإنها من أشرف أوقات الذكر.

– قال رسول الله ﷺ: «من صلى الفجر في جماعة، ثم قعد يذكر الله حتى تطلع الشمس، ثم صلى ركعتين؛ كانت له كأجر حجة وعمرة تامة تامة تامة». [حسن]

– وعن جابر بن سمرة رضي الله عنه، أن النبي ﷺ كان إذا صلى الفجر قعد في مصلاه حتى تطلع الشمس. [مسلم]

– وعنه قال: «كان ﷺ إذا صلى الفجر تربّع في مجلسه حتى تطلع الشمس حسناء». [مسلم]', 0, 'من آداب الصباح والمساء. (ص٥٩–٦١)

حاشية: ولْيتجنب الغفلة عن فضيلة هذا الوقت المبارك -الذي هو أشرف أوقات الذكر في النهار- بألّا يعاود النوم بعد صلاة الفجر؛ فقد روى صخر الغامدي رضي الله عنه أن رسول الله ﷺ قال: «اللهم بارك لأمتي في بكورها» [حسن لغيره]، قال: وكان إذا بعث سرية أو جيشًا بعثهم أول النهار، وكان صخر رجلًا تاجرًا، وكان إذا بعث تجارة بعثها أول النهار، فأثرى، وكثر ماله؛ ولذلك قال النووي رحمه الله: «يُسنُّ -لمن له وظيفة من نحو قراءة، أو علم شرعي، وتسبيح، أو اعتكاف، أو صنعة- فعله أول النهار، وكذا نحو سفر، وعقد نكاح، وإنشاء أمر».اهـ.
– ومرّ عبد الله بن عمرو رضي الله عنهما على رجل بعد صلاة الصبح، وهو نائم، فحرّكه برجله حتى استيقظ، وقال له: «أما علمت أنّ الله عز وجل يطلع في هذه الساعة إلى خلقه، فيُدخل ثلة منهم الجنة برحمته؟».
– ورأى ابن عباس رضي الله عنهما ابنًا له نائمًا نوم الصبحة، فقال له: «قُمْ! أتنام في الساعة التي تُقسَّم فيها الأرزاق؟!».
– وصحّ عن خوّات بن جبير، قال: «نوم أول النهار خُرق، وأوسطه خُلق، وآخره حُمق».
قوله: خُرق: أي جهل، وخُلق -بضم اللام وسكونها-، أي: أنه خلق محمود؛ لحديث: «قيلوا؛ فإن الشياطين لا تقيل» [حسن]، وقوله: حُمق؛ لأنه وضع للشيء في غير موضعه مع العلم بقبحه.
– وقال علقمة بن قيس: «بلغنا أنّ الأرض تعجُّ إلى الله تعالى من نومة العالم بعد صلاة الصبح».
– وسُئل مسعر بن كدام عن المروءة، قال: «التفقّه في الدين، ولزوم المسجد إلى أن تطلع الشمس».', '', '', 'السادس أن يمكث في مصلاه بعد صلاة الصبح يذكر الله حتى تطلع الشمس ثم يصلي ركعتين وأن يمكث كذلك يذكر الله بعد صلاة العصر فإنها من أشرف أوقات الذكر قال رسول الله من صلى الفجر في جماعة ثم قعد يذكر الله حتى تطلع الشمس ثم صلى ركعتين كانت له كأجر حجة وعمرة تامة تامة تامة حسن وعن جابر بن سمرة رضي الله عنه أن النبي كان إذا صلى الفجر قعد في مصلاه حتى تطلع الشمس مسلم وعنه قال كان إذا صلى الفجر تربع في مجلسه حتى تطلع الشمس حسناء مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1245, 106, 7, 'واعلم -رحمك الله- أن السلف كانوا يكرهون الكلام -في المسجد- بعد ركعتي الفجر، حتى تطلع الشمس:

– فعن عطاء، قال: خرج ابن مسعود رضي الله عنه على قوم يتحدثون بعد ركعتي الفجر، فنهاهم عن الحديث، وقال: «إنما جئتم للصلاة، إمّا أن تُصلّوا، وإمّا أن تسكتوا».

– وعن أبي عبيدة بن عبد الله بن مسعود، قال: «كان عزيزًا على ابن مسعود رضي الله عنه أن يتكلّم بعد طلوع الفجر إلا بذكر الله».

– وعن خُصَيف الجزري، قال: سألت سعيد بن جبير عن آية بعد الركعتين فلم يُجبْني. قال: فلما صلّى، قال: «إنه لَيُكْرَهُ الكلام بعد الركعتين»، قلت: يقول الرجل لأهله: الصلاةَ، قال: «لا بأس».

– وعن عثمان بن أبي سليمان، قال: «إذا طلع الفجر فليسكتوا، وإن كانوا رُكبانًا».

– وذُكر أن ابن المسيّب كان يقول: «أنا إذن أحمق من الذي يتكلّم بعدما يطلع الفجر».

– وقال الأوزاعي رحمه الله: «كان السلف إذا صدع الفجر كأنما على رؤوسهم الطير، مقبلين على أنفسهم، حتى لو أن حميمًا لأحدهم غاب عنه حينًا، ثم قدِم، ما التفتَ إليه، فلا يزالون كذلك حتى يكون قريبًا من طلوع الشمس».

– وقال الوليد بن مسلم: «كان الأوزاعي يبيت في مصلاه يذكر الله حتى تطلع الشمس، ويخبرنا عن السلف أن ذلك كان هديهم».

– وعن إبراهيم: أنهم كرهوا الكلام بعد ركعتي الفجر.

– وعن مالك، قال: كان سعيد بن أبي هند، ونافع مولى ابن عمر، وموسى بن ميسرة، يجلسون بعد صلاة الصبح حتى يرتفع النهار، ثم يتفرّقون، ما يُكلِّم بعضهم بعضًا. فقلنا له: اشتغالًا بذكر الله؟ قال: «كلُّ ذلك».

– وعن مجاهد، قال: رأيت ابن عمر رضي الله عنهما صلّى ركعتي الفجر، ثم احتبى، فلم يتكلّم حتى صلّى الغداة.

ومن هنا نصح الإمام ابن الجوزي ولده قائلًا: «فألزم نفسك يا بُنيَّ الانتباه عند طلوع الفجر، ولا تتحدّث بحديث الدنيا؛ فقد كان السلف الصالح رحمهم الله لا يتكلمون في ذلك الوقت بشيء من أمور الدنيا».', 0, 'من آداب الصباح والمساء. (ص٦١–٦٣)', '', '', 'واعلم رحمك الله أن السلف كانوا يكرهون الكلام في المسجد بعد ركعتي الفجر حتى تطلع الشمس فعن عطاء قال خرج ابن مسعود رضي الله عنه على قوم يتحدثون بعد ركعتي الفجر فنهاهم عن الحديث وقال إنما جئتم للصلاة إما أن تصلوا وإما أن تسكتوا وعن أبي عبيدة بن عبد الله بن مسعود قال كان عزيزا على ابن مسعود رضي الله عنه أن يتكلم بعد طلوع الفجر إلا بذكر الله وعن خصيف الجزري قال سألت سعيد بن جبير عن آية بعد الركعتين فلم يجبني قال فلما صلى قال إنه ليكره الكلام بعد الركعتين قلت يقول الرجل لأهله الصلاة قال لا بأس وعن عثمان بن أبي سليمان قال إذا طلع الفجر فليسكتوا وإن كانوا ركبانا وذكر أن ابن المسيب كان يقول أنا إذن أحمق من الذي يتكلم بعدما يطلع الفجر وقال الأوزاعي رحمه الله كان السلف إذا صدع الفجر كأنما على رؤوسهم الطير مقبلين على أنفسهم حتى لو أن حميما لأحدهم غاب عنه حينا ثم قدم ما التفت إليه فلا يزالون كذلك حتى يكون قريبا من طلوع الشمس وقال الوليد بن مسلم كان الأوزاعي يبيت في مصلاه يذكر الله حتى تطلع الشمس ويخبرنا عن السلف أن ذلك كان هديهم وعن إبراهيم أنهم كرهوا الكلام بعد ركعتي الفجر وعن مالك قال كان سعيد بن أبي هند ونافع مولى ابن عمر وموسى بن ميسرة يجلسون بعد صلاة الصبح حتى يرتفع النهار ثم يتفرقون ما يكلم بعضهم بعضا فقلنا له اشتغالا بذكر الله قال كل ذلك وعن مجاهد قال رأيت ابن عمر رضي الله عنهما صلى ركعتي الفجر ثم احتبى فلم يتكلم حتى صلى الغداة ومن هنا نصح الإمام ابن الجوزي ولده قائلا فألزم نفسك يا بني الانتباه عند طلوع الفجر ولا تتحدث بحديث الدنيا فقد كان السلف الصالح رحمهم الله لا يتكلمون في ذلك الوقت بشيء من أمور الدنيا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1246, 106, 8, 'السابع: أن يجتهد في الجمع في يوم واحد بين صوم تطوّع، وعيادة مريض، وتشييع جنازة، وإطعام مسكين؛ فقد قال أبو هريرة رضي الله عنه: قال رسول الله ﷺ: «من أصبح منكم اليوم صائمًا؟»، قال أبو بكر: أنا. قال: «من عاد منكم اليوم مريضًا؟»، قال أبو بكر: أنا. قال: «من شهد منكم اليوم جنازةً؟»، قال أبو بكر: أنا. قال: «فمن أطعم اليوم مسكينًا؟»، قال أبو بكر: أنا. فقال رسول الله ﷺ: «ما اجتمعت هذه الخصال في رجل في يوم؛ إلا دخل الجنة». [مسلم]', 0, 'من آداب الصباح والمساء. (ص٦٤)', '', '', 'السابع أن يجتهد في الجمع في يوم واحد بين صوم تطوع وعيادة مريض وتشييع جنازة وإطعام مسكين فقد قال أبو هريرة رضي الله عنه قال رسول الله من أصبح منكم اليوم صائما قال أبو بكر أنا قال من عاد منكم اليوم مريضا قال أبو بكر أنا قال من شهد منكم اليوم جنازة قال أبو بكر أنا قال فمن أطعم اليوم مسكينا قال أبو بكر أنا فقال رسول الله ما اجتمعت هذه الخصال في رجل في يوم إلا دخل الجنة مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1247, 106, 9, 'الثامن: أن يستحضر قول رسول الله ﷺ: «من أصبح منكم آمنًا في سربه، مُعافًى في جسده، عنده قوتُ يومه؛ فكأنما حيزت له الدنيا بحذافيرها». [حسن]

وليستحضر قول رسول الله ﷺ: «يصبح على كل سُلامى من أحدكم صدقة؛ فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويُجزئ من ذلك ركعتان يركعهما من الضحى». [مسلم]', 0, 'من آداب الصباح والمساء. (ص٦٤–٦٥)

حاشية: أي: إذا مضى الليل، وأصبح الإنسان؛ يلزمه صدقة على كل سلامى.

حاشية: أصل السُّلامى: عظام الأصابع وسائر الكف، ثم استعمل في جميع عظام البدن ومفاصله، قال الخطّابي: «إن كلَّ عضو ومفصل من بدنه عليه صدقة»، والمقصود: أن كل عظم من عظام ابن آدم يصبح سليمًا عن الآفات، باقيًا على الهيئة التي تتم بها منافعه، فعليه صدقة شكرًا لمن صوّره، ووقاه عمّا يُغيّره.', '', '', 'الثامن أن يستحضر قول رسول الله من أصبح منكم آمنا في سربه معافى في جسده عنده قوت يومه فكأنما حيزت له الدنيا بحذافيرها حسن وليستحضر قول رسول الله يصبح على كل سلامى من أحدكم صدقة فكل تسبيحة صدقة وكل تحميدة صدقة وكل تهليلة صدقة وكل تكبيرة صدقة وأمر بالمعروف صدقة ونهي عن المنكر صدقة ويجزئ من ذلك ركعتان يركعهما من الضحى مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1248, 106, 10, 'التاسع: أن يبادر بكتابة وصيته بشيء من ماله -ثلث أو أقل- إذا كان له مال كثير، وورثته أغنياء، فيوصي به إلى أقربائه من غير الوارثين، أو لجهة من جهات الخير.

وإذا كان له مال عند أحد، أو كان عليه دَيْن أو عنده وديعة، أو عليه حقوق يخشى أن تضيع على أصحابها بموته؛ فيجب عليه أن يوصي بذلك حتى لا يؤاخذه الله بها، وكذا له أن يوصي بالعهد إلى من ينظر في شأن أولاده الصغار إلى بلوغهم.', 0, 'من آداب الصباح والمساء. (ص٦٥)', '', '', 'التاسع أن يبادر بكتابة وصيته بشيء من ماله ثلث أو أقل إذا كان له مال كثير وورثته أغنياء فيوصي به إلى أقربائه من غير الوارثين أو لجهة من جهات الخير وإذا كان له مال عند أحد أو كان عليه دين أو عنده وديعة أو عليه حقوق يخشى أن تضيع على أصحابها بموته فيجب عليه أن يوصي بذلك حتى لا يؤاخذه الله بها وكذا له أن يوصي بالعهد إلى من ينظر في شأن أولاده الصغار إلى بلوغهم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1249, 106, 11, 'العاشر: أن يستحضر قول الله تبارك وتعالى: ﴿ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ٤٥ ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗا ﴾ الآيتين [غافر: ٤٥، ٤٦].

عن ميمون بن مسيرة، قال: كانت لأبي هريرة رضي الله عنه صيحتان في كل يوم؛ أول النهار وآخره، يقول: «ذهب الليل، وجاء النهار، وعُرض آل فرعون على النار»، فلا يسمعه أحد إلا استعاذ بالله من النار.', 0, 'من آداب الصباح والمساء. (ص٦٦)', '', '', 'العاشر أن يستحضر قول الله تبارك وتعالى وحاق بال فرعون سوء العذاب ٤٥ النار يعرضون عليها غدوا وعشيا الآيتين غافر ٤٥ ٤٦ عن ميمون بن مسيرة قال كانت لأبي هريرة رضي الله عنه صيحتان في كل يوم أول النهار وآخره يقول ذهب الليل وجاء النهار وعرض آل فرعون على النار فلا يسمعه أحد إلا استعاذ بالله من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1227, 106, 12, 'الحادي عشر: أن يستحضر أن هذا اليوم أو هذه الليلة قد يكون آخر عهده بالحياة؛ لقوله سبحانه وتعالى: ﴿ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ ﴾ [الأعراف: ١٨٥]، وليحرص على دعاء سيد الاستغفار.

– وقد رُوي عنه ﷺ أنه قال: «أكثروا ذكر هاذم اللذات الموت؛ فإنه لم يذكره أحد في ضيق من العيش إلا وسّعه عليه، ولا ذكره في سعة إلا ضيّقها عليه»، وهاذم اللذات: قاطعها. [حسن]

– وقال ﷺ: «أتاني جبريل، فقال: يا محمد، عش ما شئت، فإنك ميّت، وأحبب من شئت فإنك مفارقه، واعمل ما شئت فإنك مجزيّ به» الحديث. [حسن]

وعن ابن عمر رضي الله عنهما قال: أخذ رسول الله ﷺ بمنكبي، فقال: «كن في الدنيا كأنك غريب أو عابر سبيل، وعُدَّ نفسك في أصحاب القبور». [البخاري]

وكان ابن عمر رضي الله عنهما يقول: «إذا أمسيتَ فلا تنتظر الصباح، وإذا أصبحتَ فلا تنتظر المساء، وخذ من صحتك لمرضك، ومن حياتك لموتك».

نموتُ ونحيا كلَّ يومٍ وليلةٍ
ولا بُدَّ من يومٍ نموتُ ولا نحيا

آخَر:

وما المرءُ إلا راكبٌ ظهرَ عمرِه
على سفرٍ يفنيه باليومِ والشهرِ
يبيتُ ويضحى كلَّ يومٍ وليلةٍ
بعيدًا عن الدنيا قريبًا إلى القبرِ

– وقال بكر المزني رحمه الله: «ما من يوم أخرجه الله إلى الدنيا إلا يقول: ابنَ آدم، اغتنمني؛ فلعلّه لا يوم لك بعدي. ولا ليلة إلا تنادي: ابنَ آدم، اغتنمني، لعلّه لا ليلة لك بعدي».', 0, 'من آداب الصباح والمساء. (ص٦٦–٦٨)

حاشية: تقدّم في الحديث رقم (٩) (ص٣٦).', '', '', 'الحادي عشر أن يستحضر أن هذا اليوم أو هذه الليلة قد يكون آخر عهده بالحياة لقوله سبحانه وتعالى وأن عسى أن يكون قد اقترب أجلهم الأعراف ١٨٥ وليحرص على دعاء سيد الاستغفار وقد روي عنه أنه قال أكثروا ذكر هاذم اللذات الموت فإنه لم يذكره أحد في ضيق من العيش إلا وسعه عليه ولا ذكره في سعة إلا ضيقها عليه وهاذم اللذات قاطعها حسن وقال أتاني جبريل فقال يا محمد عش ما شئت فإنك ميت وأحبب من شئت فإنك مفارقه واعمل ما شئت فإنك مجزي به الحديث حسن وعن ابن عمر رضي الله عنهما قال أخذ رسول الله بمنكبي فقال كن في الدنيا كأنك غريب أو عابر سبيل وعد نفسك في أصحاب القبور البخاري وكان ابن عمر رضي الله عنهما يقول إذا أمسيت فلا تنتظر الصباح وإذا أصبحت فلا تنتظر المساء وخذ من صحتك لمرضك ومن حياتك لموتك نموت ونحيا كل يوم وليلة ولا بد من يوم نموت ولا نحيا آخر وما المرء إلا راكب ظهر عمره على سفر يفنيه باليوم والشهر يبيت ويضحى كل يوم وليلة بعيدا عن الدنيا قريبا إلى القبر وقال بكر المزني رحمه الله ما من يوم أخرجه الله إلى الدنيا إلا يقول ابن آدم اغتنمني فلعله لا يوم لك بعدي ولا ليلة إلا تنادي ابن آدم اغتنمني لعله لا ليلة لك بعدي', '', '');

